# Evaluation metrics: SVS vs Self-Consistency accuracy, agreement, per-label breakdown, confusion matrix.

from __future__ import annotations

from collections import defaultdict

from svs_pipeline.types import SVSResult

LABELS = ["True", "False", "Unknown"]


def evaluate_results(results: list[SVSResult]) -> dict:
    n = len(results)
    if n == 0:
        return {"n": 0, "svs_accuracy": 0.0, "sc_accuracy": 0.0, "delta": 0.0,
                "svs_correct": 0, "sc_correct": 0, "both_correct": 0,
                "svs_only_correct": 0, "sc_only_correct": 0, "both_wrong": 0,
                "agreement_rate": 0.0, "per_label": {}, "confusion": {}}

    svs_correct = sum(r.correct_svs for r in results)
    sc_correct = sum(r.correct_sc for r in results)
    both_correct = sum(r.correct_svs and r.correct_sc for r in results)
    svs_only = sum(r.correct_svs and not r.correct_sc for r in results)
    sc_only = sum(not r.correct_svs and r.correct_sc for r in results)
    both_wrong = sum(not r.correct_svs and not r.correct_sc for r in results)
    agreement = sum(r.selected_answer == r.sc_answer for r in results)

    svs_acc = svs_correct / n
    sc_acc = sc_correct / n

    # per-label breakdown
    per_label: dict[str, dict] = {}
    by_label: dict[str, list[SVSResult]] = defaultdict(list)
    for r in results:
        by_label[r.gold_label].append(r)
    for label in LABELS:
        group = by_label[label]
        gn = len(group)
        if gn == 0:
            per_label[label] = {"n": 0, "svs_acc": 0.0, "sc_acc": 0.0}
        else:
            per_label[label] = {
                "n": gn,
                "svs_acc": sum(r.correct_svs for r in group) / gn,
                "sc_acc": sum(r.correct_sc for r in group) / gn,
            }

    # confusion matrix: predicted -> {gold: count}
    confusion: dict[str, dict[str, int]] = {
        p: {g: 0 for g in LABELS} for p in LABELS
    }
    for r in results:
        if r.selected_answer in confusion and r.gold_label in LABELS:
            confusion[r.selected_answer][r.gold_label] += 1

    return {
        "n": n,
        "svs_accuracy": svs_acc,
        "sc_accuracy": sc_acc,
        "delta": svs_acc - sc_acc,
        "svs_correct": svs_correct,
        "sc_correct": sc_correct,
        "both_correct": both_correct,
        "svs_only_correct": svs_only,
        "sc_only_correct": sc_only,
        "both_wrong": both_wrong,
        "agreement_rate": agreement / n,
        "per_label": per_label,
        "confusion": confusion,
    }


def format_report(metrics: dict) -> str:
    if metrics["n"] == 0:
        return "No results to report."

    lines = [
        f"=== SVS Evaluation Report (n={metrics['n']}) ===",
        "",
        f"SVS accuracy:  {metrics['svs_accuracy']:.4f}  ({metrics['svs_correct']}/{metrics['n']})",
        f"SC  accuracy:  {metrics['sc_accuracy']:.4f}  ({metrics['sc_correct']}/{metrics['n']})",
        f"Delta (SVS-SC): {metrics['delta']:+.4f}",
        f"Agreement rate:  {metrics['agreement_rate']:.4f}",
        "",
        "--- Overlap ---",
        f"Both correct:      {metrics['both_correct']}",
        f"SVS only correct:  {metrics['svs_only_correct']}",
        f"SC  only correct:  {metrics['sc_only_correct']}",
        f"Both wrong:        {metrics['both_wrong']}",
    ]

    if metrics["per_label"]:
        lines += ["", "--- Per Label ---"]
        for label, info in metrics["per_label"].items():
            if info["n"] > 0:
                lines.append(
                    f"  {label:>7s}  n={info['n']:<4d}  svs={info['svs_acc']:.4f}  sc={info['sc_acc']:.4f}"
                )

    if metrics["confusion"]:
        lines += ["", "--- Confusion (SVS predicted -> gold) ---"]
        lines.append(f"  {'pred\\gold':>10s}  {'True':>6s}  {'False':>6s}  {'Unknown':>7s}")
        for pred in LABELS:
            row = metrics["confusion"].get(pred, {})
            lines.append(
                f"  {pred:>10s}  {row.get('True',0):>6d}  {row.get('False',0):>6d}  {row.get('Unknown',0):>7d}"
            )

    return "\n".join(lines)

"""API cost tracker — 记录所有 LLM API 调用的 token 使用量和费用估算。"""

import logging
from dataclasses import dataclass, field
from threading import Lock

logger = logging.getLogger(__name__)

DEFAULT_PRICING = {
    "deepseek-chat": {"input": 0.14, "output": 0.28},
    "deepseek-reasoner": {"input": 0.55, "output": 2.19},
}


@dataclass
class CostTracker:
    """Thread-safe API cost tracker."""

    pricing: dict = field(default_factory=lambda: dict(DEFAULT_PRICING))
    _records: list = field(default_factory=list, repr=False)
    _lock: Lock = field(default_factory=Lock, repr=False)
    _total_input_tokens: int = 0
    _total_output_tokens: int = 0

    def record(self, model: str, prompt_tokens: int, completion_tokens: int, module: str = ""):
        with self._lock:
            self._total_input_tokens += prompt_tokens
            self._total_output_tokens += completion_tokens
            self._records.append({
                "model": model,
                "prompt_tokens": prompt_tokens,
                "completion_tokens": completion_tokens,
                "total_tokens": prompt_tokens + completion_tokens,
                "module": module,
            })
        logger.debug("API call [%s/%s]: %d+%d tokens", module, model, prompt_tokens, completion_tokens)

    def summary(self) -> dict:
        with self._lock:
            by_module: dict = {}
            by_model: dict = {}
            for r in self._records:
                mod = r["module"] or "unknown"
                if mod not in by_module:
                    by_module[mod] = {"calls": 0, "input_tokens": 0, "output_tokens": 0}
                by_module[mod]["calls"] += 1
                by_module[mod]["input_tokens"] += r["prompt_tokens"]
                by_module[mod]["output_tokens"] += r["completion_tokens"]

                mdl = r["model"]
                if mdl not in by_model:
                    by_model[mdl] = {"calls": 0, "input_tokens": 0, "output_tokens": 0}
                by_model[mdl]["calls"] += 1
                by_model[mdl]["input_tokens"] += r["prompt_tokens"]
                by_model[mdl]["output_tokens"] += r["completion_tokens"]

            total_cost = 0.0
            model_costs: dict = {}
            for mdl, counts in by_model.items():
                prices = self.pricing.get(mdl, {"input": 0.0, "output": 0.0})
                cost = (counts["input_tokens"] / 1_000_000 * prices["input"]
                        + counts["output_tokens"] / 1_000_000 * prices["output"])
                model_costs[mdl] = round(cost, 6)
                total_cost += cost

            return {
                "total_calls": len(self._records),
                "total_input_tokens": self._total_input_tokens,
                "total_output_tokens": self._total_output_tokens,
                "total_tokens": self._total_input_tokens + self._total_output_tokens,
                "estimated_cost_usd": round(total_cost, 6),
                "by_module": by_module,
                "by_model": {
                    mdl: {**counts, "estimated_cost_usd": model_costs.get(mdl, 0)}
                    for mdl, counts in by_model.items()
                },
            }


_global_tracker = CostTracker()


def get_tracker() -> CostTracker:
    return _global_tracker


def reset_tracker():
    global _global_tracker
    _global_tracker = CostTracker()

"""Vocabulary normalizer: extract shared predicate/constant vocabularies from problems.

Ensures all chains for a problem use the same predicate and constant names,
which is critical for cross-chain logical coherence (CCLC) — without shared
vocabulary, Z3 treats different symbol names as independent and the conjunction
becomes trivially satisfiable.

Input: Problem (premises + hypothesis)
Output: dict with "predicates" and "constants" mappings
"""

import logging
import json
import re

from openai import OpenAI

from ..types import Problem
from ..config import APIConfig
from ..cost_tracker import get_tracker

logger = logging.getLogger(__name__)

# Regex patterns for ProofWriter's stylized English
_ENTITY_PAT = re.compile(
    r"\b(?:The\s+)?([A-Z][a-z]+(?:\s+[A-Z][a-z]+)?)\b"
    r"(?=\s+(?:is|likes|chases|sees|visits|eats|needs|does))"
)
_UNARY_IS_PAT = re.compile(
    r"\b(?:The\s+)?(\w+)\s+is\s+(?:not\s+)?(\w+)\b"
)
_BINARY_VERB_PAT = re.compile(
    r"\b(?:The\s+)?(\w+)\s+(likes|chases|sees|visits|eats|needs|does\s+not\s+\w+|does\s+\w+)\s+(?:the\s+)?(\w+)\b",
    re.IGNORECASE,
)

_LLM_VOCAB_PROMPT = """\
You are a logic formalization assistant. Given a set of natural language premises and a hypothesis, \
extract a shared vocabulary of predicates and constants for first-order logic formalization.

**Rules:**
- Predicates are properties (unary) or relations (binary). Use CamelCase names.
- Constants are named entities. Use lowercase snake_case.
- Every predicate and constant that appears in the premises or hypothesis must be included.
- Do NOT invent predicates/constants not grounded in the text.

**Output format (strict JSON, no extra text):**
```json
{
  "predicates": {
    "PredicateName": {"arity": 1, "description": "short description"},
    ...
  },
  "constants": {
    "entity_name": {"sort": "entity", "description": "short description"},
    ...
  }
}
```

Premises:
{premises}

Hypothesis:
{hypothesis}

Extract the vocabulary now. Output only the JSON object."""


class VocabNormalizer:
    def __init__(self, api_config: APIConfig | None = None):
        self._api = api_config
        if api_config:
            self._client = OpenAI(
                base_url=api_config.base_url,
                api_key=[REDACTED],
                timeout=api_config.timeout,
            )

    def extract_vocab(self, problem: Problem) -> dict:
        """Auto-select extraction mode: regex for ProofWriter, LLM for others."""
        if problem.dataset == "proofwriter":
            vocab = self.normalize_vocab_regex(problem)
            if vocab["predicates"] or vocab["constants"]:
                logger.info(
                    "Regex extraction for %s: %d predicates, %d constants",
                    problem.id,
                    len(vocab["predicates"]),
                    len(vocab["constants"]),
                )
                return vocab
            logger.warning(
                "Regex extraction empty for %s, falling back to LLM", problem.id
            )
        return self.normalize_vocab_llm(problem)

    # ------------------------------------------------------------------
    # Regex-based extraction (ProofWriter)
    # ------------------------------------------------------------------

    def normalize_vocab_regex(self, problem: Problem) -> dict:
        predicates: dict[str, dict] = {}
        constants: dict[str, dict] = {}

        all_text = problem.premises + [problem.hypothesis]

        for sent in all_text:
            self._extract_unary(sent, predicates, constants)
            self._extract_binary(sent, predicates, constants)

        # second pass: pick up entity names that only appeared as objects
        for sent in all_text:
            for m in _ENTITY_PAT.finditer(sent):
                name = m.group(1).lower().replace(" ", "_")
                if name not in constants and name not in {
                    p.lower() for p in predicates
                }:
                    constants[name] = {"sort": "entity", "description": name}

        return {"predicates": predicates, "constants": constants}

    @staticmethod
    def _extract_unary(
        sent: str, predicates: dict, constants: dict
    ) -> None:
        for m in _UNARY_IS_PAT.finditer(sent):
            subj = m.group(1).lower().replace(" ", "_")
            prop = m.group(2).capitalize()
            if prop.lower() in ("not", "a", "an", "the"):
                continue
            predicates.setdefault(
                prop, {"arity": 1, "description": f"is {prop.lower()}"}
            )
            constants.setdefault(
                subj, {"sort": "entity", "description": subj}
            )

    @staticmethod
    def _extract_binary(
        sent: str, predicates: dict, constants: dict
    ) -> None:
        for m in _BINARY_VERB_PAT.finditer(sent):
            subj = m.group(1).lower().replace(" ", "_")
            verb = m.group(2).strip().split()[0].capitalize()
            obj = m.group(3).lower().replace(" ", "_")
            pred_name = verb
            # "does not chase" → "Chase" (negation handled at FOL level)
            if verb.lower() == "does":
                parts = m.group(2).strip().split()
                if len(parts) >= 2:
                    pred_name = parts[-1].capitalize()
            predicates.setdefault(
                pred_name, {"arity": 2, "description": f"{pred_name.lower()}s"}
            )
            constants.setdefault(
                subj, {"sort": "entity", "description": subj}
            )
            constants.setdefault(
                obj, {"sort": "entity", "description": obj}
            )

    # ------------------------------------------------------------------
    # LLM-based extraction (FOLIO and fallback)
    # ------------------------------------------------------------------

    def normalize_vocab_llm(self, problem: Problem) -> dict:
        if not self._api:
            raise ValueError("LLM vocab extraction requires an APIConfig")

        premises_text = "\n".join(
            f"{i+1}. {p}" for i, p in enumerate(problem.premises)
        )
        prompt = _LLM_VOCAB_PROMPT.format(
            premises=premises_text, hypothesis=problem.hypothesis
        )

        last_error = None
        for attempt in range(self._api.max_retries):
            try:
                resp = self._client.chat.completions.create(
                    model=self._api.formalization_model,
                    messages=[{"role": "user", "content": prompt}],
                    temperature=0.0,
                    max_tokens=1024,
                )
                if hasattr(resp, 'usage') and resp.usage:
                    get_tracker().record(
                        model=self._api.formalization_model,
                        prompt_tokens=resp.usage.prompt_tokens or 0,
                        completion_tokens=resp.usage.completion_tokens or 0,
                        module="vocab_normalizer",
                    )
                text = resp.choices[0].message.content.strip()
                vocab = self._parse_vocab_json(text)
                logger.info(
                    "LLM vocab extraction for %s (attempt %d): %d predicates, %d constants",
                    problem.id,
                    attempt + 1,
                    len(vocab["predicates"]),
                    len(vocab["constants"]),
                )
                return vocab
            except Exception as e:
                last_error = e
                logger.warning(
                    "LLM vocab extraction attempt %d failed for %s: %s",
                    attempt + 1,
                    problem.id,
                    e,
                )

        logger.error(
            "LLM vocab extraction failed for %s after %d attempts: %s",
            problem.id,
            self._api.max_retries,
            last_error,
        )
        return {"predicates": {}, "constants": {}}

    @staticmethod
    def _parse_vocab_json(text: str) -> dict:
        # Strip markdown code fences if present
        text = re.sub(r"```(?:json)?\s*", "", text).strip()
        text = text.rstrip("`").strip()

        data = json.loads(text)
        vocab: dict = {"predicates": {}, "constants": {}}

        for name, info in data.get("predicates", {}).items():
            vocab["predicates"][name] = {
                "arity": int(info.get("arity", 1)),
                "description": str(info.get("description", "")),
            }
        for name, info in data.get("constants", {}).items():
            vocab["constants"][name] = {
                "sort": str(info.get("sort", "entity")),
                "description": str(info.get("description", name)),
            }
        return vocab

"""Cross-chain logical coherence (CCLC) checker.

Merges formalized claims across chains sharing the same answer and checks
whether the combined set is satisfiable. Provides both full-group and
pairwise compatibility diagnostics.
"""

import logging
import re
from itertools import combinations

from ..types import AtomicClaim
from ..config import VerificationConfig
from .z3_checker import Z3Checker

logger = logging.getLogger(__name__)

_PREDICATE_RE = re.compile(r'[A-Z][a-zA-Z]*(?=\()')
_CONSTANT_RE = re.compile(r'\b[a-z][a-z_]*\b')
_QUANTIFIER_VARS = frozenset({"x", "y", "z", "w"})
_Z3_KEYWORDS = frozenset({
    "and", "or", "not", "implies", "if", "else", "true", "false",
    "forall", "exists", "int", "bool",
})


def _extract_predicates(fol: str) -> set[str]:
    return set(_PREDICATE_RE.findall(fol))


def _extract_constants(fol: str) -> set[str]:
    raw = set(_CONSTANT_RE.findall(fol))
    return raw - _QUANTIFIER_VARS - _Z3_KEYWORDS


class CrossChainChecker:

    def __init__(self, config: VerificationConfig):
        self.config = config
        self.z3_checker = Z3Checker(config)

    def check_cross_chain_compatibility(
        self, chain_claims: dict[int, list[AtomicClaim]], vocab: dict
    ) -> tuple[bool, float, dict]:
        """Check cross-chain logical coherence for an answer group.

        Args:
            chain_claims: mapping chain_id -> list of AtomicClaim (same answer)
            vocab: vocabulary dict for building Z3 context

        Returns:
            (is_sat, cclc_score, diagnostics)
        """
        merged = []
        per_chain_formalized: dict[int, list[AtomicClaim]] = {}
        for chain_id, claims in chain_claims.items():
            fc = [c for c in claims if c.z3_parseable and c.fol]
            per_chain_formalized[chain_id] = fc
            merged.extend(fc)

        per_chain_predicates: dict[int, set[str]] = {}
        per_chain_constants: dict[int, set[str]] = {}
        for chain_id, fc in per_chain_formalized.items():
            preds: set[str] = set()
            consts: set[str] = set()
            for c in fc:
                preds |= _extract_predicates(c.fol)
                consts |= _extract_constants(c.fol)
            per_chain_predicates[chain_id] = preds
            per_chain_constants[chain_id] = consts

        all_pred_sets = [s for s in per_chain_predicates.values() if s]
        all_const_sets = [s for s in per_chain_constants.values() if s]

        if len(all_pred_sets) >= 2:
            pred_union = set().union(*all_pred_sets)
            pred_intersect = all_pred_sets[0].copy()
            for s in all_pred_sets[1:]:
                pred_intersect &= s
            predicate_overlap = len(pred_intersect) / len(pred_union) if pred_union else 0.0
        else:
            predicate_overlap = 1.0

        if len(all_const_sets) >= 2:
            const_union = set().union(*all_const_sets)
            const_intersect = all_const_sets[0].copy()
            for s in all_const_sets[1:]:
                const_intersect &= s
            constant_overlap = len(const_intersect) / len(const_union) if const_union else 0.0
        else:
            constant_overlap = 1.0

        diagnostics: dict = {
            "total_merged_claims": len(merged),
            "predicate_overlap": predicate_overlap,
            "constant_overlap": constant_overlap,
            "trivially_sat": False,
            "per_chain_predicates": {
                cid: sorted(preds) for cid, preds in per_chain_predicates.items()
            },
        }

        if not merged:
            diagnostics["trivially_sat"] = True
            return (True, 1.0, diagnostics)

        is_sat, ic_score, mcs_size = self.z3_checker.check_internal_consistency(
            merged, vocab
        )

        if is_sat:
            trivially_sat = predicate_overlap == 0.0 and len(all_pred_sets) >= 2
            diagnostics["trivially_sat"] = trivially_sat
            if trivially_sat:
                logger.warning(
                    "Cross-chain trivially SAT: %d merged claims have zero predicate "
                    "overlap — vocab normalization may have failed",
                    len(merged),
                )
            else:
                logger.info("Cross-chain SAT: %d merged claims consistent", len(merged))
            return (True, 1.0, diagnostics)

        formalized_count = len(merged)
        cclc_score = mcs_size / formalized_count if formalized_count > 0 else 1.0
        logger.info(
            "Cross-chain UNSAT: MCS=%d/%d, cclc=%.3f",
            mcs_size, formalized_count, cclc_score,
        )
        return (False, cclc_score, diagnostics)

    def pairwise_compatibility(
        self, chain_claims: dict[int, list[AtomicClaim]], vocab: dict
    ) -> dict[tuple[int, int], bool]:
        """Check pairwise compatibility between every pair of chains.

        Returns:
            dict mapping (chain_i, chain_j) -> is_compatible
        """
        chain_ids = sorted(chain_claims.keys())
        results = {}

        for ci, cj in combinations(chain_ids, 2):
            pair_claims = {ci: chain_claims[ci], cj: chain_claims[cj]}
            is_sat, _, _ = self.check_cross_chain_compatibility(pair_claims, vocab)
            results[(ci, cj)] = is_sat
            logger.debug("Pair (%d, %d): %s", ci, cj, "SAT" if is_sat else "UNSAT")

        return results

